829	       lv_area_get_height(&txt_coords) >= LV_LABEL_HINT_HEIGHT_LIMIT) {
830	        label_draw_dsc.hint = &label->hint;
831	    }
832	#endif
833	
834	    label_draw_dsc.flag = flag;
835	    label_draw_dsc.base.layer = layer;
836	    lv_obj_init_draw_label_dsc(obj, LV_PART_MAIN, &label_draw_dsc);
837	    lv_bidi_calculate_align(&label_draw_dsc.align, &label_draw_dsc.bidi_dir, label->text);
