901	
902	            lv_draw_label(layer, &label_draw_dsc, &txt_coords);
903	        }
904	
905	        /*Draw the text again below the original to make a circular effect */
906	        if(size.y > lv_area_get_height(&txt_coords)) {
907	            label_draw_dsc.ofs_x = label->offset.x;
908	            label_draw_dsc.ofs_y = label->offset.y + size.y + lv_font_get_line_height(label_draw_dsc.font);
909	
910	            lv_draw_label(layer, &label_draw_dsc, &txt_coords);
911	        }
912	    }
913	
914	    layer->_clip_area = clip_area_ori;
915	}
